Arguments: {"cwd":null,"title":"Pull 2026 regular season games and venues from MLB API","code":"const tabId = 845789509;

const gamesData = await browserjs(tabId, async () => {
  const url = "https://statsapi.mlb.com/api/v1/schedule?sportId=1&season=2026&gameType=R&hydrate=team,venue";
  const res = await fetch(url);
  const data = await res.json();

  // Extract all games
  const allGames = [];
  const venues = new Map();
  const teams = new Map();

  for (const d of data.dates || []) {
    for (const g of d.games || []) {
      const homeTeam = g.teams?.home?.team?.name;
      const homeId = g.teams?.home?.team?.id;
      const awayTeam = g.teams?.away?.team?.name;
      const awayId = g.teams?.away?.team?.id;
      const venue = g.venue?.name;
      const venueId = g.venue?.id;

      venues.set(venueId, venue);
      teams.set(homeId, homeTeam);

      allGames.push({
        gamePk: g.gamePk,
        date: d.date,
        homeTeam,
        homeId,
        awayTeam,
        awayId,
        venue,
        venueId,
        dayNight: g.dayNight
      });
    }
  }

  return {
    totalGames: allGames.length,
    sample: allGames.slice(0, 5),
    venueList: Array.from(venues.entries()),
    teamList: Array.from(teams.entries()),
    dateRange: {
      first: allGames[0]?.date,
      last: allGames[allGames.length - 1]?.date
    }
  };
});

console.log("Total regular season games:", gamesData.totalGames);
console.log("Date range:", gamesData.dateRange);
console.log("Venues count:", gamesData.venueList.length);
console.log("Venues:", gamesData.venueList);
"}
